def solve_equation(b, f):
    """Checks if 2 * 3^f + 3^(b-f) = 2^(b+1) - 1"""
    lhs = 2 * (3**f) + (3**(b - f))
    rhs = (2**(b + 1)) - 1
    return lhs == rhs

solutions = []
for b in range(1, 11):
    for f in range(0, b + 1):
        if solve_equation(b, f):
            solutions.append((b, f))

print("Solutions (b, f):")
for sol in solutions:
    print(sol)
